import { useState } from 'react'
import { useNavigate } from 'react-router-dom'
import Button from '../Button'
import Tag from '../Tag'
import {
  Card,
  Descricao,
  Titulo,
  Infos,
  Imagem,
  Conteudo,
  Nota
} from './styles'
import star from '../../assets/images.nova/star.svg'
import Modal from '../Modal' // Importe o Modal

type Props = {
  title: string
  description: string
  infos: string[]
  image: string
  nota: number
  id: number
  $isHome?: boolean
}

const Product = ({
  description,
  image,
  infos,
  title,
  nota,
  id,
  $isHome = true
}: Props) => {
  const navigate = useNavigate()
  const [modalIsOpen, setModalIsOpen] = useState(false) // Estado para controlar o modal

  const handleNavigate = () => {
    if ($isHome) {
      navigate(`/prato/${id}`) // Navega para a página de detalhes do prato usando o id
    } else {
      setModalIsOpen(true) // Abre o modal na página 1
    }
  }

  const closeModal = () => {
    setModalIsOpen(false) // Fecha o modal
  }

  return (
    <>
      <Card $isHome={$isHome} onClick={handleNavigate}>
        {/* Renderiza Infos e Tags apenas se $isHome for true */}
        {$isHome && (
          <Infos>
            {infos.map((info) => (
              <Tag key={info}>{info}</Tag>
            ))}
          </Infos>
        )}
        <Imagem src={image} alt={title} $isHome={$isHome} />
        <Descricao>
          <div>
            <Titulo>{title}</Titulo>
            {$isHome && (
              <Nota>
                {nota}
                <img src={star} alt="Rating" />
              </Nota>
            )}
          </div>
          <Conteudo>{description}</Conteudo>
          <Button
            type="button"
            title={$isHome ? 'Saiba mais' : 'Adicionar ao carrinho'}
            onClick={handleNavigate}
            $fullWidth={!$isHome}
            $isHome={$isHome}
          >
            {$isHome ? 'Saiba mais' : 'Adicionar ao carrinho'}
          </Button>
        </Descricao>
      </Card>

      {/* Renderiza o modal se estiver na página 1 */}
      {!$isHome && (
        <Modal
          isOpen={modalIsOpen}
          onClose={closeModal}
          image={image}
          title={title}
          description={description}
        />
      )}
    </>
  )
}

export default Product
